<script setup lang="ts">
import {computed} from 'vue'
import {useWorkspace} from '@/domain/store'
import {confirmEntries,stages,type Package} from '@/domain/model'
import {Button} from '@/components/ui/button'
const {projects,role,person,openPackage,page}=useWorkspace()
// 已归档的包已移出在办统计，只保留在历史库里查看。
const allPackages=computed(()=>projects.value.flatMap(proj=>proj.packages.filter(pkg=>!pkg.archivedAt).map(pkg=>({...pkg,projectName:proj.name,projectId:proj.id}))))
const distribution=computed(()=>stages.map(stage=>({stage,count:allPackages.value.filter(p=>p.stage===stage).length})))
const blockers=computed(()=>allPackages.value.flatMap(pkg=>confirmEntries(pkg as Package).filter(()=>role.value!=='管理员').map(e=>({id:pkg.id+e.id,packageId:pkg.id,projectName:pkg.projectName,title:e.title,owner:e.owner,assignee:e.assignee,status:'待'+e.owner+'确认'}))))
// Audit details may contain costs and prices. Show only the action and actor to other roles.
const recent=computed(()=>allPackages.value.flatMap(pkg=>pkg.audit.slice(0,6).map((a,index)=>({...a,id:pkg.id+index,packageName:pkg.packageName,projectName:pkg.projectName,packageId:pkg.id}))).slice(0,8))
const myWaiting=computed(()=>blockers.value.filter(r=>r.assignee===person.value).length)
function open(packageId:string){openPackage(packageId)}
</script>
<template><div class="insight-grid"><section class="panel"><div class="panel-heading"><div><h2>报价包阶段分布</h2><p class="muted">当前本地报价包 · {{allPackages.length}} 个</p></div></div><div class="stage-distribution"><div v-for="row in distribution" :key="row.stage"><span>{{row.stage}}</span><div class="bar-track"><div :style="{width:(allPackages.length?row.count/allPackages.length*100:0)+'%'}"/></div><b>{{row.count}}</b></div></div></section><section class="panel"><div class="panel-heading"><div><h2>待确认字段 <span class="count">{{blockers.length}}</span></h2><p class="muted">其中 {{myWaiting}} 项由我处理</p></div></div><div class="insight-scroll"><button v-for="r in blockers" :key="r.id" class="attention-row" @click="open(r.packageId)"><b>{{r.title}}</b><small>{{r.projectName}} · {{r.assignee}}</small><span>{{r.status}}</span></button><div v-if="!blockers.length" class="empty">当前没有待补齐的串字段</div></div></section><section class="panel activity-panel"><div class="panel-heading"><div><h2>近期报价包动态</h2><p class="muted">各报价包最近操作；展示操作名称，价格详情在授权页面查看</p></div><Button size="sm" variant="ghost" @click="page='overview'">项目台账 →</Button></div><div class="activity-list"><button v-for="a in recent" :key="a.id" @click="open(a.packageId)"><span class="activity-dot"/><div><b>{{a.action}}</b><small>{{a.projectName}} - {{a.packageName}} · {{a.role}} · V{{a.version}}</small></div><time>{{a.at}}</time></button><div v-if="!recent.length" class="empty">还没有项目操作记录，处理询价后会在此留存。</div></div></section></div></template>
<style scoped>.insight-grid{display:grid;grid-template-columns:1fr 1.15fr;gap:18px}.insight-grid .panel{margin:0}.stage-distribution{padding:20px;display:grid;gap:18px}.stage-distribution>div{display:grid;grid-template-columns:90px 1fr 24px;align-items:center;gap:12px;font-size:12px;color:#647787}.bar-track{height:8px;background:#edf2f6;border-radius:4px;overflow:hidden}.bar-track>div{height:100%;background:#36769c;border-radius:4px}.insight-scroll{max-height:290px;overflow:auto}.attention-row{padding:16px 20px;text-align:left;width:100%;border:0;border-bottom:1px solid #edf1f5;background:white}.attention-row>b,.attention-row small,.attention-row>span{display:block}.attention-row>b{font-size:13px}.attention-row small{margin-top:6px}.attention-row>span{font-size:11px;color:#9b702c;margin-top:8px}.activity-panel{grid-column:1/-1}.activity-list{max-height:280px;overflow:auto}.activity-list button{display:flex;align-items:center;gap:14px;padding:16px 20px;border:0;border-bottom:1px solid #edf1f5;background:#fff;width:100%;text-align:left}.activity-list b{font-size:12px}.activity-list small{display:block;margin-top:5px}.activity-list time{margin-left:auto;color:#8593a0;font-size:11px}.activity-dot{width:8px;height:8px;background:#588fac;border-radius:50%}.attention-row:hover,.activity-list button:hover{background:#f7fafc}@media(max-width:900px){.insight-grid{grid-template-columns:1fr}.activity-list time{max-width:100px}}
</style>
